list_countries.code:
var response = await client.Countries.ListCountriesAsync(
    new Dictionary<string, object?> { ["search"] = "aus" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var country in ((IReadOnlyList<object?>)body["countries"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{country["id"]} {country["code"]} {country["name"]} {country["state_count"]}");

get_country.code:
var response = await client.Countries.GetCountryAsync("AU");
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var country = (IReadOnlyDictionary<string, object?>)body["country"]!;
Console.WriteLine($"{country["id"]} {country["name"]} {country["state_count"]}");

